const icons={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',plus:'M12 5v14M5 12h14',list:'M8 6h12M8 12h12M8 18h12M3 6h.1M3 12h.1M3 18h.1',wallet:'M3 6h17v14H3z M3 6V4h14v2 M16 11h5v5h-5z',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2z M9 7h6M9 11h6M9 15h3',arrow:'M7 17L17 7M7 7h10v10',check:'M5 12l4 4L19 6',camera:'M3 7h4l2-3h6l2 3h4v13H3z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',close:'M6 6l12 12M6 18L18 6',back:'M15 5l-7 7 7 7',bag:'M4 7h16v14H4z M8 7V5a4 4 0 0 1 8 0v2',food:'M4 3v7h6V3M7 3v18M18 3v18M18 3c-5 3-5 10 0 10',car:'M5 7l2-4h10l2 4M3 7h18v11H3zM6 18v3M18 18v3M6 12h2M16 12h2',info:'M12 11v6M12 7h.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',logout:'M9 3H3v18h6M12 12h9M17 8l4 4-4 4',settings:'M4 7h16M4 17h16M9 4v6M15 14v6'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.receipt}"/></svg>`;
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(v)=>Number(v).toLocaleString('zh-TW',{maximumFractionDigits:2});
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dayAgo=(n)=>{const d=new Date();d.setDate(d.getDate()-n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const PROJECTS=[{id:'demo-a',name:'示範案 A｜活動執行'},{id:'demo-b',name:'示範案 B｜場地佈置'}];
const KEY='ankuan-demo-v1';
const seed=()=>[
{id:'seed1',project:'demo-a',date:dayAgo(8),type:'fund',amount:10000,desc:'公司撥付備用金',category:'公司給款',payment:'轉帳',status:'免附'},
{id:'seed2',project:'demo-a',date:dayAgo(4),type:'expense',amount:6000,desc:'活動器材租借',category:'其他',payment:'轉帳',status:'已核准'},
{id:'seed3',project:'demo-a',date:dayAgo(2),type:'expense',amount:1260,desc:'工作人員午餐',category:'餐飲',payment:'現金',status:'待審核'},
{id:'seed4',project:'demo-a',date:dayAgo(1),type:'expense',amount:380,desc:'現場停車費',category:'交通',payment:'現金',status:'待補件'},
{id:'seed5',project:'demo-a',date:today(),type:'expense',amount:920,desc:'指示牌與文具',category:'材料',payment:'刷卡',status:'待審核'},
{id:'seed6',project:'demo-b',date:dayAgo(3),type:'fund',amount:5000,desc:'公司撥付備用金',category:'公司給款',payment:'轉帳',status:'免附'},
{id:'seed7',project:'demo-b',date:dayAgo(1),type:'expense',amount:7200,desc:'展場佈置材料',category:'材料',payment:'轉帳',status:'已核准'}
];
let records;let storageOk=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');records=Array.isArray(saved)?saved:seed();}catch{records=seed();storageOk=false;}
let state={logged:false,view:'home',project:PROJECTS[0].id,filter:'all',draft:null,last:null};
try{state.logged=sessionStorage.getItem('ankuan-entered')==='yes';}catch{}
const app=document.querySelector('#app');let receiptData=null;let submitting=false;
const delta=r=>(r.type==='fund'||r.type==='refund')?r.amount:-r.amount;
const rows=()=>records.filter(r=>r.project===state.project);
const balance=()=>rows().reduce((a,r)=>a+delta(r),0);
const balanceTitle=()=>balance()<0?'公司還要補給你':'你手上應剩';
const types={expense:'我付了錢',refund:'收到退款',return:'退錢給公司',fund:'公司給款'};
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(records));storageOk=true;return true;}catch{storageOk=false;return false;}};
const toast=(text)=>{const box=document.querySelector('#toast');box.textContent=text;box.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.style.display='none',3500)};
const brand=()=>`<div class="brand-mark">${icon('receipt')}</div><div>案款<small>隨手記帳</small></div>`;
const projectSelector=()=>`<div class="project-select"><label for="project">目前案件</label><select id="project">${PROJECTS.map(p=>`<option value="${p.id}" ${p.id===state.project?'selected':''}>${p.name}</option>`).join('')}</select></div>`;
const nav=()=>`<button class="nav-button ${state.view==='home'?'active':''}" data-view="home">${icon('home')}我的首頁</button><button class="nav-button ${state.view==='add'?'active':''}" data-view="add">${icon('plus')}記一筆</button><button class="nav-button ${state.view==='records'?'active':''}" data-view="records">${icon('list')}我的紀錄</button>`;
const badge=s=>`<span class="badge ${s==='待補件'?'orange':s==='已核准'?'green':''}">${esc(s)}</span>`;
function entry(r){return `<button class="entry" data-detail="${esc(r.id)}"><span class="entry-icon ${delta(r)>0?'incoming':''}">${icon(r.type==='fund'?'wallet':r.category==='餐飲'?'food':r.category==='交通'?'car':'bag')}</span><span class="entry-body"><span class="entry-title">${esc(r.desc)}</span><span class="entry-meta">${esc(r.date.slice(5).replace('-','/'))}<span>·</span>${esc(r.category)}${badge(r.status)}</span></span><span class="entry-money ${delta(r)>0?'positive':''}">${delta(r)>0?'+':'−'}${money(r.amount)}</span></button>`}
function sorted(data){return [...data].sort((a,b)=>b.date.localeCompare(a.date)||records.indexOf(b)-records.indexOf(a))}
function login(){return `<div class="login-wrap"><div class="login-visual"><div class="eyebrow">每個案件，都算清楚</div><h2>花了多少，<br>隨手記下就好。</h2><div class="sample-card"><span>示範案 A · 個人餘額</span><p>你手上應剩</p><strong><small style="font-size:20px">NT$</small> 1,440</strong><div class="sample-line"><span>備用金與代墊，同一本帳</span>${icon('check')}</div></div><p>記花費、拍收據、看餘額。<br>每個案件各自結算。</p></div><div><div class="login-card"><div class="brand">${brand()}</div><h1>今天的花費，<br>今天就記好。</h1><p>先試記一筆，看看你的案件餘額。</p><button class="google-button" disabled><span class="g-logo">G</span>Google 登入，正式版開放</button><button class="primary" id="enter">進入試用版 ${icon('arrow')}</button><p class="preview-note">示範身分：小安<br>試填內容不會寫入公司 Sheets。</p></div><div class="login-bottom">手機與電腦皆適用 · 不需安裝</div></div></div>`}
function home(){const a=rows(), b=balance(),spent=a.reduce((n,r)=>n+(r.type==='expense'?r.amount:r.type==='refund'?-r.amount:0),0),funds=a.filter(r=>r.type==='fund').reduce((n,r)=>n+r.amount,0),missing=a.filter(r=>r.status==='待補件').length;return `<div class="heading"><div><h1>小安，今天辛苦了</h1><p class="subtext">記一筆花費，帳就清楚一點。</p></div>${projectSelector()}</div><div class="dashboard"><section class="balance-card"><div class="balance-top"><span>你的案件餘額</span><span class="tag">獨立結算</span></div><div><div class="balance-title">${balanceTitle()}</div><div class="money"><small>NT$</small>${money(Math.abs(b))}</div></div><div class="balance-foot">${icon('info')} ${b<0?'你的代墊已超過公司給款':'公司給款與退款，扣除花費及退回款項'}</div></section><div class="summary"><section class="stat"><span class="stat-title">${icon('wallet')}公司已給款</span><span class="stat-value">${money(funds)}</span><small>本案累計 · 元</small></section><section class="stat"><span class="stat-title">${icon('bag')}你已花費</span><span class="stat-value">${money(spent)}</span><small>已扣除退款 · 元</small></section><button class="stat attention" id="missing"><span class="stat-title">${icon('receipt')}待補收據</span><span class="stat-value">${missing}<span style="font-size:13px;font-weight:400"> 筆</span></span><small>點這裡補齊</small></button><section class="stat"><span class="stat-title">${icon('check')}待審核</span><span class="stat-value">${a.filter(r=>r.status==='待審核').length}<span style="font-size:13px;font-weight:400"> 筆</span></span><small>憑證審核進度</small></section></div></div><div class="quick-action"><div><strong>剛付完錢？順手記下來</strong><p>填金額、事由，再拍張收據。</p></div><button class="primary" data-view="add">${icon('plus')}記一筆</button></div><section><div class="section-head"><h2>最近的紀錄</h2><button class="text-button" data-view="records">查看全部</button></div><div class="panel">${sorted(a).slice(0,4).map(entry).join('')||'<div class="empty">還沒有紀錄，先記第一筆吧。</div>'}</div></section>`}
function freshDraft(){return{type:'expense',category:'餐飲',amount:'',desc:'',date:today(),payment:'現金',note:''}}
function add(){const d=state.draft||(state.draft=freshDraft());return `<div class="heading"><div><h1>記一筆</h1><p class="subtext">這筆花費，記在你自己的名下。</p></div>${projectSelector()}</div><div class="form-layout"><form id="entry-form" class="panel form-panel"><div class="segmented" aria-label="往來類型">${['expense','refund','return'].map(t=>`<button type="button" data-type="${t}" class="${d.type===t?'active':''}" aria-pressed="${d.type===t}">${types[t]}</button>`).join('')}</div><div class="amount-box"><label for="amount">${d.type==='expense'?'花了多少':d.type==='refund'?'收到多少退款':'退回多少'}</label><div class="amount-input"><span>NT$</span><input id="amount" name="amount" type="text" inputmode="decimal" placeholder="0" value="${esc(d.amount)}" required maxlength="12" autocomplete="off" aria-label="金額"></div></div><label class="field"><span>事由</span><input name="desc" maxlength="100" value="${esc(d.desc)}" placeholder="例如：工作人員午餐" required></label><div class="field-grid"><label class="field"><span>日期</span><input type="date" name="date" value="${d.date}" required max="${today()}"></label><label class="field"><span>付款方式</span><select name="payment">${['現金','轉帳','刷卡','其他'].map(p=>`<option ${p===d.payment?'selected':''}>${p}</option>`).join('')}</select></label></div><div class="field"><span>分類</span><div class="category-chips">${['餐飲','交通','材料','住宿','其他'].map(c=>`<button type="button" class="chip ${c===d.category?'active':''}" data-category="${c}" aria-pressed="${c===d.category}">${c}</button>`).join('')}</div></div><div class="field"><span>收據照片 <span style="color:#7f9196;font-weight:400">· 稍後補也行</span></span><button class="upload" type="button" id="upload-button">${receiptData?`<img class="receipt-preview" src="${receiptData}" alt="待登記收據">`:icon('camera')}<span>${receiptData?'照片已選好':'拍照或選擇照片'}<small>${receiptData?'點選更換照片':'支援 JPG、PNG、WebP，最大 10 MB'}</small></span></button><input type="file" accept="image/jpeg,image/png,image/webp" id="receipt-file" hidden>${receiptData?'<button type="button" class="text-button" id="remove-receipt">移除照片</button>':''}</div><label class="field"><span>補充說明 <span style="color:#7f9196;font-weight:400">· 選填</span></span><textarea name="note" maxlength="300" placeholder="有需要交代的事，再寫在這裡。">${esc(d.note)}</textarea></label><p class="error-text form-error" role="alert" id="form-error"></p><div class="form-footer"><button class="primary" type="submit">${icon('check')}儲存這筆試填</button><p>僅存於這台裝置，不會送進公司帳本。</p></div></form><aside class="help-panel"><h2>這筆會怎麼算？</h2><div class="help-row"><span>記帳人</span><strong>小安（示範）</strong></div><div class="help-row"><span>${balanceTitle()}</span><strong>$${money(Math.abs(balance()))}</strong></div><hr><div class="help-row"><span>${types[d.type]}</span><strong>${d.type==='refund'?'增加餘額':'扣除餘額'}</strong></div><p>公司給款由管理者登記。<br>憑證核准不等於公司已補款。</p></aside></div>`}
function recordsView(){const a=sorted(rows().filter(r=>state.filter==='all'||r.status===state.filter));return `<div class="heading"><div><h1>我的紀錄</h1><p class="subtext">花費與收據，都在這裡。</p></div>${projectSelector()}</div><div class="filters">${[['all','全部'],['待補件','待補收據'],['待審核','待審核'],['已核准','已核准']].map(([v,l])=>`<button class="chip ${state.filter===v?'active':''}" data-filter="${v}">${l}</button>`).join('')}</div><div class="record-summary"><span>${a.length} 筆紀錄</span><span>最新日期優先 · 金額為餘額增減</span></div><div class="panel">${a.map(entry).join('')||`<div class="empty">${icon('check')}<div>這裡沒有待處理的紀錄。</div></div>`}</div>`}
function success(){const r=state.last;return `<section class="success"><div class="success-mark">${icon('check')}</div><h1>這筆試填記好了</h1><p>${esc(r.desc)} · ${esc(r.date)}</p><div class="success-amount">$${money(r.amount)}</div><p>${storageOk?'已儲存在這台裝置。':'本次暫存成功，關閉頁面後不會保留。'}<br>尚未寫入公司 Sheets。</p><div class="success-balance"><span>${balanceTitle()}</span><strong>$${money(Math.abs(balance()))}</strong></div><button class="primary" data-view="add">${icon('plus')}再記一筆</button><button class="secondary" data-view="home">回到我的首頁</button></section>`}
function settings(){return `<div class="heading"><div><h1>試用設定</h1><p class="subtext">先試操作，再串接正式帳本。</p></div></div><div class="panel settings-panel"><h2>目前是示範模式</h2><p>示範姓名、案件與款項皆為試用資料。Google 登入與 Sheets 尚未連線。試填內容只留在目前瀏覽器。</p><p>正式版將以 Google 帳號對應員工名單，並依案件限制讀寫權限。</p><button class="secondary" id="reset">重設示範資料</button><button class="text-button" id="logout" style="margin-left:18px">回登入畫面</button></div>`}
function render(){if(!state.logged){app.innerHTML=login();document.querySelector('#enter').onclick=()=>{state.logged=true;try{sessionStorage.setItem('ankuan-entered','yes')}catch{}render()};return}app.innerHTML=`<aside class="sidebar"><div class="brand">${brand()}</div><nav>${nav()}</nav><div class="side-footer">每案一份帳，各自結清。<br><button data-view="settings">試用設定</button></div></aside><main class="main"><header class="topbar"><div class="crumb">個人工作台 / ${state.view==='add'?'記一筆':state.view==='records'?'我的紀錄':'我的首頁'}</div><div class="brand mobile-brand">${brand()}</div><button class="profile" data-view="settings" style="background:none;color:inherit;padding:0" aria-label="小安的試用設定"><span class="avatar">安</span><span><strong>小安</strong><small>示範帳號</small></span></button></header>${state.view==='home'?home():state.view==='add'?add():state.view==='records'?recordsView():state.view==='success'?success():settings()}</main><nav class="bottom-nav" aria-label="主要導覽"><button data-view="home" class="${state.view==='home'?'active':''}">${icon('home')}首頁</button><button data-view="add" class="${state.view==='add'?'active':''}"><span class="add-circle">${icon('plus')}</span>記一筆</button><button data-view="records" class="${state.view==='records'?'active':''}">${icon('list')}我的紀錄</button></nav>`;bind();}
function navigate(view){if(!['home','add','records','settings','success'].includes(view))throw Error('Unknown view');state.view=view;if(view==='add'&&!state.draft)state.draft=freshDraft();render();window.scrollTo({top:0,behavior:'instant'})}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelector('#project')?.addEventListener('change',e=>{state.project=e.target.value;render()});document.querySelector('#missing')?.addEventListener('click',()=>{state.filter='待補件';navigate('records')});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{state.draft.type=b.dataset.type;render()});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.draft.category=b.dataset.category;render()});const form=document.querySelector('#entry-form');if(form){form.addEventListener('input',e=>{if(e.target.name)state.draft[e.target.name]=e.target.value});form.addEventListener('change',e=>{if(e.target.name)state.draft[e.target.name]=e.target.value});form.addEventListener('submit',saveEntry);document.querySelector('#upload-button').onclick=()=>document.querySelector('#receipt-file').click();document.querySelector('#receipt-file').onchange=async e=>{if(e.target.files[0]){try{receiptData=await readPhoto(e.target.files[0]);render()}catch(err){document.querySelector('#form-error').textContent=err.message}}};document.querySelector('#remove-receipt')?.addEventListener('click',()=>{receiptData=null;render()})}document.querySelector('#logout')?.addEventListener('click',()=>{state.logged=false;try{sessionStorage.removeItem('ankuan-entered')}catch{}render()});document.querySelector('#reset')?.addEventListener('click',()=>{const modal=document.querySelector('#detail');modal.innerHTML=`<h2>重設示範資料？</h2><p>這台裝置的試填紀錄與照片會清除，恢復初始示範帳。</p><div style="display:flex;gap:12px"><button class="secondary" id="cancel-reset">保留紀錄</button><button class="primary" id="confirm-reset">重設</button></div>`;modal.showModal();document.querySelector('#cancel-reset').onclick=()=>modal.close();document.querySelector('#confirm-reset').onclick=()=>{records=seed();persist();state.draft=null;receiptData=null;modal.close();navigate('home');toast('已恢復示範資料')}})}
async function readPhoto(file){if(file.size>10*1024*1024)throw Error('照片超過 10 MB，請選較小的檔案。');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('請選 JPG、PNG 或 WebP 照片。');const url=URL.createObjectURL(file);try{const img=await new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=()=>rej(Error('照片讀取失敗，請重新選取。'));i.src=url});const scale=Math.min(1,1400/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.75)}finally{URL.revokeObjectURL(url)}}
function saveEntry(e){e.preventDefault();if(submitting)return;const d=state.draft,amount=Number(d.amount);let error='';if(!/^\d+(\.\d{1,2})?$/.test(d.amount)||!Number.isFinite(amount)||amount<=0||amount>99999999)error='請填大於 0 的金額，最多兩位小數。';else if(!d.desc.trim())error='請填這筆款項的事由。';else if(!/^\d{4}-\d{2}-\d{2}$/.test(d.date)||d.date>today())error='請確認日期，日期不得晚於今天。';if(error){document.querySelector('#form-error').textContent=error;return}submitting=true;const record={...d,amount,desc:d.desc.trim(),id:crypto.randomUUID(),project:state.project,photo:receiptData,status:d.type==='return'?'免附':receiptData?'待審核':'待補件'};records.push(record);if(!persist()){records.pop();document.querySelector('#form-error').textContent='裝置儲存空間不足或瀏覽器阻擋儲存。請縮小照片，或換一般瀏覽視窗再試。';submitting=false;return}state.last=record;state.draft=null;receiptData=null;submitting=false;navigate('success')}
function openDetail(id){const r=records.find(r=>r.id===id);if(!r)return;const modal=document.querySelector('#detail');modal.innerHTML=`<div class="dialog-head"><h2>款項明細</h2><button class="icon-button" id="close-detail" aria-label="關閉">${icon('close')}</button></div><div class="success-amount" style="margin-top:0">${delta(r)>0?'+':'−'}$${money(r.amount)}</div>${[['事由',r.desc],['案件',PROJECTS.find(p=>p.id===r.project).name],['記帳人','小安（示範）'],['日期',r.date],['往來',types[r.type]],['付款方式',r.payment],['憑證進度',r.status],...(r.note?[['補充說明',r.note]]:[])].map(([k,v])=>`<div class="details-line"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}${r.photo?`<img class="detail-image" alt="收據照片" src="${r.photo}">`:r.status==='待補件'?'<p class="subtext" style="margin:20px 0">這筆還缺收據，拍照補上就完成了。</p>':'<p class="subtext" style="margin:20px 0">此示範紀錄未附實際照片。</p>'}${r.status==='待補件'?`<input type="file" id="detail-file" accept="image/jpeg,image/png,image/webp" hidden><button class="primary" id="add-photo" style="width:100%;margin-top:15px">${icon('camera')}補上收據</button>`:''}<p class="error-text" id="detail-error" role="alert"></p><p class="subtext" style="font-size:12px;margin-top:20px">憑證審核與公司補款分開計算。</p>`;if(!modal.open)modal.showModal();document.querySelector('#close-detail').onclick=()=>modal.close();document.querySelector('#add-photo')?.addEventListener('click',()=>document.querySelector('#detail-file').click());document.querySelector('#detail-file')?.addEventListener('change',async e=>{if(!e.target.files[0])return;try{const photo=await readPhoto(e.target.files[0]);const old={photo:r.photo,status:r.status};r.photo=photo;r.status='待審核';if(!persist()){r.photo=old.photo;r.status=old.status;throw Error('裝置儲存空間不足，請縮小照片後再試。')}render();openDetail(id);toast('收據已補上，進度改為待審核')}catch(err){document.querySelector('#detail-error').textContent=err.message}})}
render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_demo_project_balance',title:'讀取示範案餘額',description:'Read the current device-local demo project balance. Does not read Google Sheets.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({project:state.project,balance:balance(),companyOwes:Math.max(0,-balance()),fundsHeld:Math.max(0,balance()),mode:'device-local-demo'})});document.modelContext.registerTool({name:'navigate_demo_view',title:'切換試用畫面',description:'Navigate the demo interface without creating records or submitting to Sheets.',inputSchema:{type:'object',properties:{view:{type:'string',enum:['home','add','records']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({view})=>{if(!state.logged)throw Error('Enter the demo first.');if(!['home','add','records'].includes(view))throw Error('Invalid demo view.');navigate(view);return{view:state.view,mode:'device-local-demo'}}})}catch{}}
